/* Operative Data and Prediction Markets: UK energy markets — application script.
   DATA (bundled above): SNAP = fallback fact-box series, CON = fallback contract prices, SERIES = the daily data
   file as it was when the page was built, QUOTES = the media selection as it was when the page was built.
   Live in the browser: Polymarket (gamma-api), Manifold (api.manifold.markets), the data behind Ofgem's charts
   (app.everviz.com), the gov.uk content API (UK ETS tables), the IMF commodity API (Brent, TTF).
   Everything else (DESNZ DUKES and Energy Trends spreadsheets, NSTA, DESNZ heat pumps, HMRC pages, NESO) is read
   daily by scripts/fetch_series.py into data/series.json, which the hosted page fetches on load. */

const REFRESH_MS = 60_000, DATA_MS = 30*60_000, EMBED_MS = 10*60_000;
const two_years_ago = (()=>{ const d=new Date(); d.setDate(d.getDate()-740); return d.toISOString().slice(0,10); })();

