/* ---------- live fetchers (publishers that allow cross-origin reads) ---------- */
async function getText(u, ms=25000, headers){ const c=new AbortController(); const t=setTimeout(()=>c.abort(),ms); try{ const r=await fetch(u,{signal:c.signal, headers}); if(!r.ok) throw new Error(r.status); return await r.text(); } finally{ clearTimeout(t); } }
async function getJSON(u, ms=25000){ return JSON.parse(await getText(u,ms)); }
function csvRows(text, delim){ // RFC4180-ish
  const rows=[]; let row=[], cell="", q=false;
  for(let i=0;i<text.length;i++){ const ch=text[i];
    if(q){ if(ch==='"'){ if(text[i+1]==='"'){cell+='"';i++;} else q=false; } else cell+=ch; }
    else if(ch==='"') q=true; else if(ch===delim){ row.push(cell); cell=""; } else if(ch==='\n'){ row.push(cell); rows.push(row); row=[]; cell=""; } else if(ch!=='\r') cell+=ch; }
  if(cell!==""||row.length){ row.push(cell); rows.push(row); }
  return rows.filter(r=>r.length>1);
}
async function everviz(id){
  const js = await getText("https://app.everviz.com/inject/"+id, 30000);
  const m = js.match(/"data":\{"csv":"((?:[^"\\]|\\.)*)"/); if(!m) throw new Error("no csv");
  const csv = JSON.parse('"'+m[1]+'"'); const first=csv.split("\n")[0];
  const rows = csvRows(csv, (first.split(";").length>first.split(",").length)?";":",");
  const asof = (js.match(/correct as of:?\s*([A-Za-z]+ \d{4})/)||[])[1];
  return {header: rows[0].map(h=>h.trim()), rows: rows.slice(1).filter(r=>r[0]&&r[0].trim()), asof};
}
const MON3 = {Jan:1,Feb:2,Mar:3,Apr:4,May:5,Jun:6,Jul:7,Aug:8,Sep:9,Oct:10,Nov:11,Dec:12};
const pMDY = s => { const [mm,,yy]=s.trim().replace(/"/g,"").split("/"); return `${yy}-${mm}`; };
const pMonYY = s => { const [mm,yy]=s.trim().split("-"); return `20${yy} Q${Math.ceil(MON3[mm]/3)}`; };
const pQ = s => { let m=s.trim().match(/^Q(\d) (\d{4})$/); if(m) return `${m[2]} Q${m[1]}`; m=s.trim().match(/^(\d{4}) Q(\d)$/); return m?`${m[1]} Q${m[2]}`:null; };
const pCap = s => { const m=s.trim().match(/^([A-Z][a-z]{2})[a-z]*\s*-\s*[A-Z][a-z]+\s+(\d{2}|\d{4})$/); if(!m) return null; const y=m[2].length===4?m[2]:"20"+m[2]; return `${y} Q${Math.ceil(MON3[m[1]]/3)}`; };
const n = v => { const x=parseFloat(v); return isFinite(x)?x:null; };
const LIVE = {
  power: async()=>{ const e=await everviz("n9WSDfgxc"); return {rows:e.rows.filter(r=>n(r[1])!=null).map(r=>[pMDY(r[0]),+n(r[1]).toFixed(2)]).slice(-24), asof:e.asof}; },
  nbp:   async()=>{ const e=await everviz("YFsS4g98P"); return {rows:e.rows.filter(r=>n(r[1])!=null).map(r=>[pMDY(r[0]),+n(r[1]).toFixed(2)]).slice(-24), asof:e.asof}; },
  cap:   async()=>{ const e=await everviz("lVeuoASKI"); const H=e.header.map(h=>h.toLowerCase()); const jt=H.indexOf("total"), jw=H.findIndex(h=>h.startsWith("wholesale")), jd=H.findIndex(h=>h.startsWith("debt related")), je=H.findIndex(h=>h.startsWith("earnings before"));
           return {rows:e.rows.map(r=>[pCap(r[0]), Math.round(n(r[jt])), Math.round(n(r[jw])||0), Math.round(n(r[jd])||0), Math.round(n(r[je])||0)]).filter(r=>r[0]&&isFinite(r[1])).slice(-10), asof:e.asof}; },
  debt:  async()=>{ const e=await everviz("0IwJatYrR"); return {rows:e.rows.map(r=>[pQ(r[0]), n(r[3]), n(r[1]), n(r[2])]).filter(r=>r[0]&&r[1]!=null).slice(-10), asof:e.asof}; },
  suppliers: async()=>{ const e=await everviz("-7wWeiqwF"); const jt=e.header.map(h=>h.toLowerCase()).indexOf("total"); return {rows:e.rows.filter(r=>n(r[jt])!=null).map(r=>[pMonYY(r[0]), Math.round(n(r[jt]))]).slice(-10), asof:e.asof}; },
  shares_e: async()=>shares("_o5LqZ5Dk"), shares_g: async()=>shares("4GHD8gVq8"),
  switch: async()=>{ const e=await everviz("eGQWqcSLx"); return {rows:e.rows.filter(r=>n(r[1])!=null).map(r=>[pMDY(r[0]), +(n(r[1])/1000).toFixed(1), +(n(r[2])/1000).toFixed(1)]).slice(-24), asof:e.asof}; },
  uka:   async()=>{ const d=await getJSON("https://www.gov.uk/api/content/government/publications/taking-part-in-the-uk-emissions-trading-scheme-markets/cost-containment-mechanism-ccm-trigger-prices-and-average-monthly-prices-full-table");
           const doc=new DOMParser().parseFromString(d.details.body,"text/html"); const ser={}, trig={};
           doc.querySelectorAll("table tr").forEach(tr=>{ const c=[...tr.querySelectorAll("td,th")].map(x=>x.textContent.trim()); if(!c.length||!/^[A-Z][a-z]{2}-\d\d$/.test(c[0])) return;
             const [mm,yy]=c[0].split("-"); const y=2000+ +yy, m=MON3[mm]; const k=c.length-5; if(c[2].startsWith("£")) trig[`${y}-${String(m).padStart(2,"0")}`]=+c[2].slice(1).replace(/,/g,"");
             c.slice(4,4+k).forEach((p,i)=>{ const ym=y*12+m-1-(k-i); const yy2=Math.floor(ym/12), mm2=ym%12+1; if(p.startsWith("£")) ser[`${yy2}-${String(mm2).padStart(2,"0")}`]=+p.slice(1).replace(/,/g,""); }); });
           const rows=Object.entries(ser).sort().map(([p,v])=>[p,v]).slice(-24); const tr=Object.entries(trig).sort().slice(-3);
           return {rows, trigger:tr, asof:(d.public_updated_at||"").slice(0,10)}; },
  brent: async()=>imf("POILBRE","USD"), ttf: async()=>imf("PNGASEU","USD"),
};
async function shares(id){ const e=await everviz(id); const rows=[]; for(const r of e.rows){ const p=pQ(r[0]); if(!p) continue; const d={}; e.header.forEach((h,j)=>{ if(j&&n(r[j])) d[h]=+n(r[j]).toFixed(2); }); rows.push([p,d]); } return {rows:rows.slice(-9), asof:e.asof}; }
async function imf(indicator, transform){
  const t = await getText(`https://api.imf.org/external/sdmx/2.1/data/IMF.RES,PCPS/G001.${indicator}.${transform}.M?startPeriod=${two_years_ago.slice(0,7)}`, 30000, {Accept:"application/vnd.sdmx.data+csv"});
  const rows=csvRows(t,","); const h=rows[0]; const it=h.indexOf("TIME_PERIOD"), iv=h.indexOf("OBS_VALUE");
  return {rows: rows.slice(1).filter(r=>r[iv]&&r[it]).map(r=>[r[it].replace("-M","-"),+(+r[iv]).toFixed(2)]).filter(r=>isFinite(r[1])).sort()};
}

